import React, { useState, useRef, useEffect } from 'react';
import {
  Box,
  Container,
  Typography,
  Card,
  CardContent,
  CardActions,
  Chip,
  Button,
  IconButton,
  Stack,
} from '@mui/material';
import ArrowBackRoundedIcon from '@mui/icons-material/ArrowBackRounded';
import ArrowForwardRoundedIcon from '@mui/icons-material/ArrowForwardRounded';
import QrCodeScannerRoundedIcon from '@mui/icons-material/QrCodeScannerRounded';
import PhonelinkRoundedIcon from '@mui/icons-material/PhonelinkRounded';
import GitHubIcon from '@mui/icons-material/GitHub';
import NorthEastRoundedIcon from '@mui/icons-material/NorthEastRounded';
import { TranslationContent } from '../../translations';
import './MyProjects.css';

interface ProjectsProps {
  t: TranslationContent['projects'];
}

const MyProjects: React.FC<ProjectsProps> = ({ t }) => {
  const trackRef = useRef<HTMLDivElement>(null);
  const [canScrollLeft, setCanScrollLeft] = useState(false);
  const [canScrollRight, setCanScrollRight] = useState(true);

  const checkScroll = () => {
    if (!trackRef.current) return;
    const { scrollLeft, scrollWidth, clientWidth } = trackRef.current;
    setCanScrollLeft(scrollLeft > 10);
    setCanScrollRight(scrollLeft < scrollWidth - clientWidth - 10);
  };

  useEffect(() => {
    checkScroll();
    const el = trackRef.current;
    if (!el) return;
    el.addEventListener('scroll', checkScroll, { passive: true });
    window.addEventListener('resize', checkScroll);
    return () => {
      el.removeEventListener('scroll', checkScroll);
      window.removeEventListener('resize', checkScroll);
    };
  }, []);

  const handleScroll = (direction: 'left' | 'right') => {
    if (!trackRef.current) return;
    const scrollAmount = 370;
    trackRef.current.scrollBy({
      left: direction === 'left' ? -scrollAmount : scrollAmount,
      behavior: 'smooth',
    });
  };

  return (
    <Box
      id="proyectos-autonomos"
      component="section"
      className="autonomous-projects-section"
      sx={{
        backgroundColor: '#f0f6fd', // Fondo celeste claro (Zebra)
        py: { xs: 8, md: 12 },
        position: 'relative',
        borderTop: '1px solid #d2e4f7',
        borderBottom: '1px solid #d2e4f7',
      }}
    >
      <Container maxWidth="xl">
        {/* Section Header with Horizontal Scroll Controls */}
        <Box
          sx={{
            display: 'flex',
            flexDirection: { xs: 'column', md: 'row' },
            justifyContent: 'space-between',
            alignItems: { xs: 'flex-start', md: 'center' },
            gap: 2.5,
            mb: 5,
          }}
        >
          <Box sx={{ maxWidth: 760 }}>
            <Typography
              variant="h2"
              component="h2"
              sx={{
                fontSize: { xs: '2.2rem', sm: '2.8rem', md: '3.4rem' },
                fontWeight: 800,
                letterSpacing: '-0.03em',
                lineHeight: 1.15,
                mb: 1,
                color: '#0f172a',
              }}
            >
              {t.title}
            </Typography>

            <Typography
              variant="body1"
              sx={{
                fontSize: { xs: '1rem', md: '1.12rem' },
                color: '#475569',
                lineHeight: 1.6,
              }}
            >
              {t.subtitle}
            </Typography>
          </Box>

          {/* Navigation Controls */}
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, flexShrink: 0 }}>
            <IconButton
              onClick={() => handleScroll('left')}
              disabled={!canScrollLeft}
              sx={{
                backgroundColor: '#ffffff',
                border: '1px solid #cbd5e1',
                color: '#003366',
                boxShadow: '0 2px 8px rgba(0,0,0,0.04)',
                '&:hover': {
                  backgroundColor: '#f8fafc',
                  borderColor: '#003366',
                },
                '&.Mui-disabled': {
                  opacity: 0.35,
                },
              }}
              aria-label="Retroceder proyectos"
            >
              <ArrowBackRoundedIcon />
            </IconButton>

            <IconButton
              onClick={() => handleScroll('right')}
              disabled={!canScrollRight}
              sx={{
                backgroundColor: '#003366',
                border: '1px solid #003366',
                color: '#ffffff',
                boxShadow: '0 4px 12px rgba(0, 51, 102, 0.25)',
                '&:hover': {
                  backgroundColor: '#002244',
                },
                '&.Mui-disabled': {
                  backgroundColor: '#cbd5e1',
                  borderColor: '#cbd5e1',
                  color: '#ffffff',
                  opacity: 0.5,
                },
              }}
              aria-label="Avanzar proyectos"
            >
              <ArrowForwardRoundedIcon />
            </IconButton>
          </Box>
        </Box>

        {/* Content with Continuous Horizontal Scroll Track */}
        <Box
          ref={trackRef}
          className="projects-scroll-track"
          sx={{
            display: 'flex',
            gap: 3.5,
            overflowX: 'auto',
            pt: 2,
            pb: 3,
            scrollSnapType: 'x mandatory',
            '&::-webkit-scrollbar': {
              height: 8,
            },
            '&::-webkit-scrollbar-thumb': {
              backgroundColor: '#cbd5e1',
              borderRadius: '999px',
            },
            '&::-webkit-scrollbar-track': {
              backgroundColor: '#e2e8f0',
              borderRadius: '999px',
            },
          }}
        >
          {t.items.map((project) => (
            <Card
              key={project.id}
              elevation={0}
              className="project-card-horizontal"
              sx={{
                flex: '0 0 auto',
                width: { xs: 290, sm: 360, md: 390 },
                scrollSnapAlign: 'start',
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'space-between',
                backgroundColor: '#ffffff',
                border: '1px solid #d2e4f7',
                borderRadius: '22px',
                overflow: 'hidden',
                boxShadow: '0 8px 24px rgba(0, 51, 102, 0.04)',
                transition: 'all 0.3s cubic-bezier(0.16, 1, 0.3, 1)',
                '&:hover': {
                  transform: 'translateY(-6px)',
                  borderColor: '#003366',
                  boxShadow: '0 20px 45px rgba(0, 51, 102, 0.12)',
                },
              }}
            >
              {/* Project Image or Clean Placeholder */}
              <Box
                sx={{
                  width: '100%',
                  height: 200,
                  backgroundColor: project.id === 'menuqr' || project.id === 'tuqr' ? '#ffffff' : '#e9f1fa',
                  borderBottom: '1px solid #d2e4f7',
                  position: 'relative',
                  overflow: 'hidden',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                }}
              >
                {project.imageUrl ? (
                  <Box
                    component="img"
                    src={project.imageUrl}
                    alt={project.title}
                    sx={{
                      width: '100%',
                      height: '100%',
                      objectFit: project.id === 'menuqr' || project.id === 'tuqr' ? 'contain' : 'cover',
                      p: project.id === 'menuqr' || project.id === 'tuqr' ? 2.5 : 0,
                      transition: 'transform 0.3s ease',
                      '&:hover': {
                        transform: 'scale(1.03)',
                      },
                    }}
                  />
                ) : (
                  /* Clean Placeholder */
                  <Box
                    sx={{
                      textAlign: 'center',
                      p: 3,
                      display: 'flex',
                      flexDirection: 'column',
                      alignItems: 'center',
                      gap: 1.5,
                    }}
                  >
                    <Box
                      sx={{
                        width: 54,
                        height: 54,
                        borderRadius: '14px',
                        backgroundColor: '#ffffff',
                        border: '1px solid #cbd5e1',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        boxShadow: '0 4px 12px rgba(0, 51, 102, 0.08)',
                      }}
                    >
                      {project.id === 'menuqr' ? (
                        <QrCodeScannerRoundedIcon sx={{ fontSize: 28, color: '#003366' }} />
                      ) : (
                        <PhonelinkRoundedIcon sx={{ fontSize: 28, color: '#003366' }} />
                      )}
                    </Box>
                    <Typography
                      variant="caption"
                      sx={{
                        color: '#64748b',
                        fontWeight: 700,
                        letterSpacing: '0.05em',
                        textTransform: 'uppercase',
                        fontSize: '0.76rem',
                      }}
                    >
                      {project.placeholderText || 'Placeholder Preview'}
                    </Typography>
                  </Box>
                )}
              </Box>

              <CardContent sx={{ p: { xs: 2.5, md: 3 }, flex: 1 }}>
                <Box sx={{ mb: 1.8 }}>
                  <Typography
                    variant="h5"
                    sx={{
                      fontWeight: 800,
                      color: '#0f172a',
                      fontSize: { xs: '1.3rem', md: '1.45rem' },
                      letterSpacing: '-0.02em',
                      mb: 1,
                    }}
                  >
                    {project.title}
                  </Typography>

                  <Chip
                    label={project.category}
                    size="small"
                    sx={{
                      backgroundColor: 'rgba(0, 51, 102, 0.06)',
                      color: '#003366',
                      fontWeight: 600,
                      fontSize: '0.72rem',
                      borderRadius: '6px',
                      border: '1px solid rgba(0, 51, 102, 0.12)',
                    }}
                  />
                </Box>

                <Typography
                  variant="body2"
                  sx={{
                    color: '#475569',
                    lineHeight: 1.65,
                    fontSize: '0.92rem',
                    mb: 2.5,
                  }}
                >
                  {project.description}
                </Typography>

                <Stack direction="row" spacing={0.8} flexWrap="wrap" useFlexGap>
                  {project.tags.map((tag, i) => (
                    <Chip
                      key={i}
                      label={tag}
                      size="small"
                      sx={{
                        backgroundColor: '#f8fafc',
                        color: '#334155',
                        border: '1px solid #e2e8f0',
                        fontSize: '0.72rem',
                        fontWeight: 600,
                        borderRadius: '6px',
                      }}
                    />
                  ))}
                </Stack>
              </CardContent>

              <CardActions sx={{ px: { xs: 2.5, md: 3 }, pb: { xs: 2.5, md: 3 }, pt: 0 }}>
                <Button
                  variant="outlined"
                  href={project.linkUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  fullWidth
                  startIcon={project.isExternalRepo ? <GitHubIcon /> : undefined}
                  endIcon={!project.isExternalRepo ? <NorthEastRoundedIcon /> : undefined}
                  sx={{
                    borderColor: '#cbd5e1',
                    color: '#003366',
                    fontWeight: 600,
                    fontSize: '0.88rem',
                    py: 1,
                    borderRadius: '10px',
                    textTransform: 'none',
                    '&:hover': {
                      borderColor: '#003366',
                      backgroundColor: '#003366',
                      color: '#ffffff',
                    },
                  }}
                >
                  {project.linkLabel}
                </Button>
              </CardActions>
            </Card>
          ))}
        </Box>
      </Container>
    </Box>
  );
};

export default MyProjects;
